-- v97: 英语阅读短文 15篇 — 5类话题各3篇，生词率≤3%，120词/篇
INSERT IGNORE INTO precision_reading_seeds (title, topic, content, difficulty, week, word_count, new_words, questions_json) VALUES
-- === 校园生活类 (3篇) ===
('My First Day at School','校园','I still remember my first day at vocational school. I was a little nervous because I did not know anyone. But soon I made new friends. My teacher was very kind. She showed us around the school and told us about the rules. We have many interesting subjects like computer science and English. I like computer science best. After school, I often play basketball with my classmates. I think I will enjoy my life here very much. I want to work hard and become a good programmer.',1,1,120,'nervous/kind/subject/programmer','[{"q":"How did the writer feel on the first day?","options":["Happy","Nervous","Angry","Bored"],"answer":"B"},{"q":"What is the writer''s favorite subject?","options":["English","Math","Computer Science","Basketball"],"answer":"C"},{"q":"What does the writer want to become?","options":["A teacher","A doctor","A programmer","A basketball player"],"answer":"C"}]'),
('My Daily Life','校园','Every morning, I get up at six thirty. After washing my face, I have breakfast at seven. I usually eat bread and drink milk. Then I walk to school. It takes about fifteen minutes. Classes begin at eight. We have four classes in the morning and two in the afternoon. Between classes, I like to talk with my friends. Lunch time is from twelve to one. The food in our school is good. After school, I do my homework first, then I play computer games for a while. I go to bed at ten.',1,1,118,'wash/enjoy','[{"q":"What time does the writer get up?","options":["6:00","6:30","7:00","7:30"],"answer":"B"},{"q":"How many classes does the writer have each day?","options":["4","5","6","8"],"answer":"C"},{"q":"What does the writer do after homework?","options":["Watch TV","Play games","Read books","Sleep"],"answer":"B"}]'),
('A Letter to My Friend','校园','Dear Li Ming, How are you doing? I am writing to tell you about my new school. It is not very big but it is beautiful. There are about eight hundred students here. I study many subjects, but my favorite is English. I think English is very useful for my future job. Our English teacher is young and friendly. She always encourages us to speak more English in class. I have made some good friends here. We often study together and help each other. Please write back and tell me about your school life. Yours, Wang Lei',2,2,110,'encourage/useful/friendly','[{"q":"Who is the letter to?","options":["Wang Lei","Li Ming","The teacher","Parents"],"answer":"B"},{"q":"What is the writer''s favorite subject?","options":["Math","Chinese","English","Computer"],"answer":"C"},{"q":"What does the teacher encourage students to do?","options":["Read more","Write more","Speak more English","Listen more"],"answer":"C"}]'),
-- === 趣味科普类 (3篇) ===
('Why Do We Sleep?','科普','Do you know why we need to sleep? When we sleep, our body and brain get some rest. Scientists say that sleep helps us remember things we learned during the day. A good night of sleep can make you feel better and think more clearly. Most people need about eight hours of sleep every night. Children and young people need even more, about nine to ten hours. If you do not get enough sleep, you may feel tired and cannot pay attention in class. So remember, go to bed early tonight! Getting enough sleep is as important as studying hard.',1,1,115,'scientist/clearly/enough/attention','[{"q":"How many hours of sleep do most people need?","options":["6","7","8","9"],"answer":"C"},{"q":"What can sleep help us do?","options":["Eat more","Remember things","Run faster","Sing better"],"answer":"B"},{"q":"What happens if you don''t get enough sleep?","options":["Feel happy","Feel tired","Feel hungry","Feel excited"],"answer":"B"}]'),
('The Power of the Sun','科普','The sun is the closest star to our earth. It gives us light and heat. Without the sun, there would be no life on earth. The sun is very big — about one million earths could fit inside it! Plants use sunlight to make food. This is called photosynthesis. Animals and humans eat plants, so we all depend on the sun for energy. People can also use sunlight to make electricity. This is called solar power. Solar power is clean and will never run out. Many countries are now building solar farms to get energy from the sun.',2,3,115,'million/photosynthesis/electricity/solar/energy','[{"q":"What does the sun give us?","options":["Only light","Only heat","Light and heat","Water"],"answer":"C"},{"q":"How do plants make food using sunlight?","options":["Breathing","Photosynthesis","Drinking","Sleeping"],"answer":"B"},{"q":"Why is solar power good?","options":["It is cheap","It is clean and never runs out","It is colorful","It is fast"],"answer":"B"}]'),
('How Does the Internet Work?','科普','When you send a message to your friend on the Internet, do you know how it travels? Your message is broken into small pieces called packets. Each packet travels through many computers and cables around the world. They may go under the ocean through thick cables! When all packets arrive at your friend''s computer, they are put back together into the original message. This all happens in less than one second. The Internet connects billions of people. It has changed the way we work, learn, and communicate. What an amazing invention!',2,4,110,'packet/cable/billion/communicate/invention','[{"q":"What are the small pieces of a message called?","options":["Letters","Packets","Words","Numbers"],"answer":"B"},{"q":"How fast does the message travel?","options":["One hour","One minute","Less than one second","One day"],"answer":"C"},{"q":"What has the Internet changed?","options":["Only work","Only learning","The way we work, learn and communicate","Nothing"],"answer":"C"}]'),
-- === 励志/文化类 (3篇) ===
('Never Give Up','励志','Thomas Edison was one of the greatest inventors in history. He invented the light bulb, but it was not easy. He tried more than one thousand times before he succeeded. When someone asked him about his failures, he said, "I have not failed. I have just found one thousand ways that do not work." Edison never gave up. His story teaches us an important lesson: success does not come easily. If you want to achieve something great, you must be willing to work hard and never give up, even when things seem impossible.',2,2,110,'inventor/bulb/succeed/failure/achieve/impossible','[{"q":"What did Edison invent?","options":["The phone","The light bulb","The computer","The radio"],"answer":"B"},{"q":"How many times did he try before success?","options":["10","100","More than 1000","1"],"answer":"C"},{"q":"What lesson does Edison''s story teach us?","options":["Give up early","Never give up","Work less","Sleep more"],"answer":"B"}]'),
('Chinese Tea Culture','文化','Tea is an important part of Chinese culture. The history of tea in China goes back more than four thousand years. There are many kinds of Chinese tea, such as green tea, black tea, and jasmine tea. People in different parts of China have different tea-drinking habits. In the south, people like to drink green tea. In some northern areas, people prefer flower tea. Drinking tea is not just about the taste. It is also a way to relax and spend time with friends and family. When guests come to visit, Chinese people often serve them tea as a sign of welcome.',2,3,118,'culture/jasmine/habit/relax/guest','[{"q":"How long is the history of tea in China?","options":["1000 years","2000 years","3000 years","Over 4000 years"],"answer":"D"},{"q":"What kind of tea do people in southern China prefer?","options":["Black tea","Green tea","Flower tea","Milk tea"],"answer":"B"},{"q":"Why do Chinese people serve tea to guests?","options":["To show welcome","To make money","To show anger","To save time"],"answer":"A"}]'),
('The Story of a Blind Runner','励志','Liu Fang is a blind girl from a small village. She lost her eyesight when she was only five years old. But she never let this stop her. She loved running from a young age. At first, she could only run with someone holding her hand. But she practiced every single day. After years of hard work, she became a professional runner. Last year, she won a gold medal at the national games for disabled athletes. Liu Fang says, "I may not see the world, but I can feel it with my heart. As long as you believe in yourself, nothing can stop you."',2,4,120,'blind/eyesight/professional/medal/disabled/athlete','[{"q":"When did Liu Fang lose her eyesight?","options":["At birth","At age 5","At age 10","At age 15"],"answer":"B"},{"q":"What did she win last year?","options":["A silver medal","A gold medal","A bronze medal","Nothing"],"answer":"B"},{"q":"What does Liu Fang say is important?","options":["Money","Fame","Believing in yourself","Speed"],"answer":"C"}]'),
-- === 职业场景类 (3篇) ===
('Job Interview Tips','职业','Are you preparing for a job interview? Here are some useful tips. First, learn about the company before the interview. Know what they do and what they need. Second, dress properly. Wear clean and tidy clothes. Third, arrive on time. Being late will leave a bad first impression. During the interview, look at the interviewer''s eyes when you speak. Speak clearly and confidently. Be honest about your skills and experience. Finally, do not forget to say thank you after the interview. A simple thank-you note can make a big difference. Good luck!',2,2,112,'interview/company/properly/impression/confidently/experience','[{"q":"What should you do before an interview?","options":["Sleep more","Learn about the company","Play games","Watch TV"],"answer":"B"},{"q":"What should you do during the interview?","options":["Look at the floor","Look at the interviewer","Close your eyes","Look at your phone"],"answer":"B"},{"q":"What should you do after the interview?","options":["Forget about it","Say thank you","Ask for money","Complain"],"answer":"B"}]'),
('My Dream Job','职业','When I was a child, I wanted to be a teacher. I liked the idea of standing in front of a classroom and helping students learn. But as I grew older, my interests changed. Now I am studying computer science at a vocational school. I want to become a software engineer. I enjoy writing code and solving problems with computers. My teacher says the IT industry is growing very fast and needs many skilled workers. I hope to find a good job after graduation. Maybe one day I will create an app that helps millions of people around the world.',2,3,115,'software/engineer/industry/skilled/graduation/create','[{"q":"What did the writer want to be as a child?","options":["A doctor","A teacher","A lawyer","A singer"],"answer":"B"},{"q":"What is the writer studying now?","options":["Art","Music","Computer science","Math"],"answer":"C"},{"q":"What does the writer hope to do after graduation?","options":["Travel","Find a good job","Sleep","Retire"],"answer":"B"}]'),
('Working in a Team','职业','In today''s workplace, teamwork is very important. Most jobs require you to work with other people. A good team member should listen to others and share ideas. Communication is the key to success. When problems come up, team members should discuss them together and find solutions. It is also important to respect different opinions. Sometimes you may disagree with others, but you should always be polite. If everyone in the team does their best, the team will achieve great results. Remember: together everyone achieves more!',2,4,105,'teamwork/require/communication/solution/respect/disagree/polite','[{"q":"What is very important in today''s workplace?","options":["Working alone","Teamwork","Sleeping","Eating"],"answer":"B"},{"q":"What should team members do when problems come up?","options":["Ignore them","Fight","Discuss together","Run away"],"answer":"C"},{"q":"What does TEAM stand for in the passage?","options":["Together everyone achieves more","Time eats all money","Take everything and move","The end and more"],"answer":"A"}]'),
-- === 应用文类 (3篇) ===
('A Notice about Class Meeting','应用','NOTICE: All students of Class 6, please be informed that we will have a class meeting this Friday at 4:00 PM in Room 302. The meeting will be about the coming mid-term exams. Our head teacher, Mr. Zhang, will give us important information about the exam schedule and some study tips. Please bring a notebook and a pen. The meeting will last about 45 minutes. Please do not be late. If you cannot attend, please tell the monitor before Thursday. Class Monitor: Li Wei, May 15, 2026.',2,2,105,'inform/meeting/mid-term/schedule/monitor/attend','[{"q":"When is the class meeting?","options":["Monday","Wednesday","Friday","Sunday"],"answer":"C"},{"q":"What is the meeting about?","options":["Sports day","Mid-term exams","School trip","Birthday party"],"answer":"B"},{"q":"Who should you tell if you cannot attend?","options":["The teacher","The monitor","Your parents","Your friend"],"answer":"B"}]'),
('A Thank-You Letter','应用','Dear Mrs. Wang, I am writing this letter to thank you for your help during the past year. Before I joined your English class, I was very weak in this subject. I could hardly speak a full English sentence. But you never gave up on me. You spent extra time after class to help me practice. You always encouraged me when I made mistakes. Now I can read English articles and even write short passages. My English score has improved from 45 to 75! I could not have done it without you. Thank you from the bottom of my heart. Yours sincerely, Zhang Hua',2,3,118,'subject/sentence/extra/article/score/improve/sincerely','[{"q":"Why is Zhang Hua writing this letter?","options":["To ask for help","To say thank you","To complain","To invite"],"answer":"B"},{"q":"What was Zhang Hua''s English score before?","options":["75","65","55","45"],"answer":"D"},{"q":"How much has the score improved?","options":["10","20","30","40"],"answer":"C"}]'),
('A Lost and Found Notice','应用','LOST: I lost my school bag in the library on Monday afternoon. It is a blue backpack with a small bear keychain on it. Inside the bag, there are two textbooks (English and Math), a blue pencil case, and a red notebook with my name on the first page. The bag is very important to me because it was a birthday gift from my grandmother. If you find it, please contact me at Room 506 in the school dormitory or call me at 138-xxxx-xxxx. A reward of 50 yuan will be given. Thank you very much! Finder: please help! Zhang Ming, May 20.',2,4,118,'library/backpack/keychain/textbook/notebook/grandmother/dormitory/reward','[{"q":"What color is the lost bag?","options":["Red","Blue","Black","Green"],"answer":"B"},{"q":"Where was the bag lost?","options":["Classroom","Library","Playground","Canteen"],"answer":"B"},{"q":"Why is the bag important?","options":["It is new","It is a gift from grandma","It is expensive","It is big"],"answer":"B"}]');
